public long parseMillis(String text) {
    DateTimeParser parser = requireParser();
    Chronology chrono = selectChronology(ISOChronology.getInstanceUTC());
    DateTimeParserBucket bucket = new DateTimeParserBucket(
        0, chrono, iLocale, iPivotYear, iDefaultYear);
    int newPos = parser.parseInto(bucket, text, 0);
    if (newPos >= 0 && newPos >= text.length()) {
        long millis = bucket.computeMillis(true, text);
        DateTimeZone zone = bucket.getZone();
        if (zone != null) {
            millis = zone.convertLocalToUTC(millis, false);
        }
        return millis;
    }
    if (newPos < 0) {
        newPos = ~newPos;
    }
    throw new IllegalArgumentException("Invalid format: \"" + text + "\" is malformed at \"" +
        text.substring(Math.min(newPos, text.length())) + "\"");
}
